DO $public_fks$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.refund_requests'::regclass AND conname = 'refund_requests_payment_refund_id_fkey') THEN
    ALTER TABLE public.refund_requests ADD CONSTRAINT refund_requests_payment_refund_id_fkey FOREIGN KEY (payment_refund_id) REFERENCES private.payment_refunds(id) ON DELETE RESTRICT;
  END IF;
END;
$public_fks$;
COMMIT;
